INSERT INTO "ListingDailyStats" ("ListingId","SellerId","Date","Impressions","Views","CallClicks","MessageStarts","Saves")
SELECT l."Id", l."SellerId", d::date,
       40 + abs(hashtext(l."Id"::text || d::text)) % 160,
       3 + abs(hashtext('v' || l."Id"::text || d::text)) % 18,
       abs(hashtext('c' || l."Id"::text || d::text)) % 4,
       abs(hashtext('m' || l."Id"::text || d::text)) % 3,
       abs(hashtext('s' || l."Id"::text || d::text)) % 5
FROM "Listings" l
CROSS JOIN generate_series(current_date - 59, current_date, interval '1 day') AS d
WHERE l."Id"::text LIKE '5eed%'
ON CONFLICT ("ListingId","Date") DO NOTHING;
INSERT INTO "SellerDailyStats" ("SellerId","Date","ProfileVisits")
SELECT sp."Id", d::date, 5 + abs(hashtext(sp."Id"::text || d::text)) % 30
FROM "SellerProfiles" sp
CROSS JOIN generate_series(current_date - 59, current_date, interval '1 day') AS d
WHERE sp."Id"::text LIKE '5eed%'
ON CONFLICT ("SellerId","Date") DO NOTHING;
